import {incomeChart,horizontalBars} from '../components/charts.js';
import {realMode} from '../services/api-service.js';
import {getStore,saveSupplier,saveUser,deleteSupplier,deleteUser,saveRolePermissions,resetRolePermissions,ROLES,ACTIVE_STATES,getContext} from '../services/workshop-service.js';
import {rolePermissions,permissionChecker,countPermissions} from '../services/permissions.js';
import {PERMISSION_MODULES,ROLE_ORDER,ROLE_INFO,TOTAL_PERMISSIONS,LOCKED_ROLE,REQUIRED_FOR_ADMIN} from '../data/permissions.js';
import {getReport} from '../services/dashboard-service.js';
import {e,money,field,select,checkbox,link,button,submit,form,hint,pageHeader,searchableList,bindForm,go,notify,showModal,table,badge,rowActions,confirmDelete,personCell,phoneFormat} from '../components/ui.js';
import {icon} from '../components/icons.js';
const access=role=>({Administrador:'Completo',Propietario:'Completo',Supervisor:'Órdenes / Mecánicos',Mecánico:'Diagnósticos / Órdenes asignadas',Auxiliar:'Órdenes asignadas',Administrativo:'Clientes / Pagos'})[role]||'Según rol';
export function renderMechanics({root,session}){
 const s=getStore(),staff=s.users.filter(u=>(u.roleNames||[u.role]).some(r=>['Mecánico','Supervisor','Auxiliar'].includes(r)));
 searchableList(root,{title:'Mecánicos y auxiliares',subtitle:'Consultar personal técnico registrado y sus asignaciones actuales.',actions:button('Ver asignaciones','assignments')+(permissionChecker(session.role)('usuarios','crear')&&permissionChecker(session.role)('usuarios','roles')?link('Registrar mecánico','usuarios/nuevo?rol='+encodeURIComponent('Mecánico'))+link('Registrar auxiliar','usuarios/nuevo?rol=Auxiliar'):''),placeholder:'Buscar por nombre o rol…',headers:['Trabajador','Rol','Órdenes activas','Estado'],records:staff,searchText:u=>`${u.name} ${u.role}`,row:u=>[`<strong>${e(u.name)}</strong>`,e(u.role),e(realMode?u.activeOrders:s.orders.filter(o=>ACTIVE_STATES.includes(o.state)&&(o.mechanicId===u.id||o.assistantId===u.id)).length),badge(u.active?'Activo':'Inactivo')]});
 root.querySelector('[data-action="assignments"]').onclick=()=>{const rows=s.orders.filter(o=>ACTIVE_STATES.includes(o.state)).map(o=>{const c=getContext(s,o);return [e(o.id),e(c.vehicle?.plate),e(s.users.find(u=>u.id===o.mechanicId)?.name),e(s.users.find(u=>u.id===o.assistantId)?.name||'Sin auxiliar'),badge(o.state)];});showModal('Asignaciones del personal técnico',table(['Orden','Vehículo','Mecánico','Auxiliar','Estado'],rows));};
 root.insertAdjacentHTML('beforeend',hint('El personal se administra desde Usuarios y roles. Aquí se consultan sus asignaciones. El rol define permisos; en cada orden se distingue mecánico responsable y auxiliar. Tener función técnica no concede acceso administrativo.'));
}
export function renderSuppliers({root,session}){
 const s=getStore(),can=permissionChecker(session.role);
 const open=id=>{const p=id?s.suppliers.find(p=>p.id===id):{};const dialog=showModal(id?'Editar proveedor':'Nuevo proveedor',form('DATOS DEL PROVEEDOR',field('Nombre / razón social','name',p.name||'','text','required maxlength="150"')+field('RUC','ruc',p.ruc||'','text','required inputmode="numeric" maxlength="11"')+field('Teléfono','phone',p.phone||'','tel','required maxlength="20"')+field(realMode?'Repuestos vinculados (consulta)':'Repuestos / especialidad','parts',p.parts||'','text',realMode?'disabled placeholder="Se muestra a partir de los repuestos vinculados"':'required maxlength="200"'),submit('Guardar proveedor')+button('Cancelar','cancel'),'supplier-form'));dialog.querySelector('[data-action="cancel"]').onclick=()=>dialog.close();bindForm('supplier-form',async data=>{await saveSupplier(data,id);dialog.close();notify(id?'Proveedor actualizado.':'Proveedor registrado.');go('proveedores');});};
 searchableList(root,{title:'Proveedores',subtitle:'Gestionar proveedores, repuestos y costos de referencia.',actions:can('proveedores','crear')?`<button type="button" class="primary-button" data-action="new">${icon('plus')} Nuevo proveedor</button>`:'',placeholder:'Buscar proveedor por nombre o RUC…',headers:['Proveedor','RUC','Teléfono','Repuestos','Acciones'],records:s.suppliers,searchText:p=>`${p.name} ${p.ruc}`,row:p=>[personCell(p.name),`<span class="mono">${e(p.ruc)}</span>`,e(p.phone),`<span class="tag">${e(p.parts)}</span>`,rowActions({id:p.id,name:p.name,canEdit:can('proveedores','editar'),canDelete:can('proveedores','eliminar')})],onAction:(act,id)=>{if(act==='delete'){const p=getStore().suppliers.find(x=>x.id===id);confirmDelete({title:'¿Eliminar proveedor?',message:`Vas a eliminar al proveedor <strong>${e(p?.name)}</strong> (RUC ${e(p?.ruc)}).`,onConfirm:async()=>{await deleteSupplier(id);notify('Proveedor eliminado.');go('proveedores');}});}else open(id);}});
 const newButton=root.querySelector('.module-heading [data-action="new"]');if(newButton)newButton.onclick=()=>open();
}
export function renderUsers({root,path,params,session}){
 const s=getStore(),can=permissionChecker(session.role);
 if(path[1]==='roles'){renderRoles({root,params,session},s,can);return;}
 if(['nuevo','editar'].includes(path[1])){
  if(!can('usuarios',path[1]==='nuevo'?'crear':'editar'))throw new Error('Tu rol no tiene permiso para esta acción.');
  const id=path[1]==='editar'?path[2]:null,u=id?s.users.find(u=>u.id===id):{};if(!u)throw new Error('No se encontró el usuario.');
  root.innerHTML=pageHeader(id?'Editar usuario':'Agregar usuario','Mismo formulario de alta y edición; la contraseña inicial se solicita solo al crear.')+form('DATOS DE ACCESO Y ROL',field('Nombre del trabajador','name',u.name||'','text','required maxlength="150"')+field('Nombre de usuario (único)','username',u.username||'','text','required minlength="3" maxlength="60" autocomplete="off" autocapitalize="none"')+field('Correo electrónico (único)','email',u.email||'','email','required maxlength="150"')+select('Rol asignado','role',realMode?s.roles.map(r=>r.name):ROLES,realMode?u.roleNames?.[0]||(s.roles.some(r=>r.name===params.get('rol'))?params.get('rol'):'Mecánico'):u.role||'Mecánico',realMode&&!can('usuarios','roles')?'disabled':'required')+(!id?field('Contraseña inicial (solo alta)','password','','password','required minlength="12" maxlength="72" autocomplete="new-password"'):'')+checkbox('Usuario activo','active',id?u.active:true),submit('Guardar usuario')+link('Volver a usuarios','usuarios'));
  if(realMode&&id)root.insertAdjacentHTML('beforeend',hint('Roles actuales: '+u.role+'. Seleccionar un rol adicional conserva todas las asignaciones existentes.'));
  bindForm('edit-form',async data=>{await saveUser(data,id);notify(id?'Usuario actualizado.':realMode?'Usuario registrado en el servidor.':'Usuario de demostración registrado.');go('usuarios');});return;
 }
 searchableList(root,{title:'Usuarios y roles',subtitle:'Administra trabajadores, roles y permisos del sistema.',actions:can('usuarios','crear')?link(icon('plus')+' Agregar usuario','usuarios/nuevo',true):'',placeholder:'Buscar usuario por nombre o rol…',headers:['Usuario','Nombre','Rol','Acceso','Estado','Acciones'],records:s.users,searchText:u=>`${u.username} ${u.name} ${u.role}`,row:u=>[`<strong>${e(u.username)}</strong>`,personCell(u.name,u.email),`<span class="tag tag-role">${e(u.role)}</span>`,e(access(u.role)),badge(u.active?'Activo':'Inactivo'),rowActions({editHref:'usuarios/editar/'+u.id,id:u.id,name:u.username,canEdit:can('usuarios','editar'),canDelete:can('usuarios','eliminar')})],onAction:(act,id)=>{if(act!=='delete')return;const u=getStore().users.find(x=>x.id===id);confirmDelete({title:'¿Eliminar usuario?',message:`Vas a eliminar al usuario <strong>${e(u?.username)}</strong> (${e(u?.name)}, ${e(u?.role)}).`,onConfirm:async()=>{await deleteUser(id,session.id);notify('Usuario eliminado.');go('usuarios');}});}});
 root.querySelector('.list-panel').insertAdjacentHTML('beforebegin',userTabs('usuarios'));
 root.insertAdjacentHTML('beforeend',hint(realMode?'Los permisos se verifican en Go. Asignar un rol agrega esa relación y conserva los roles adicionales existentes.':'Accesos de demostración. Los usuarios nuevos pueden iniciar sesión localmente; la autorización definitiva se implementará en el servidor.'));
}
export async function renderReports({root}){
 const today=new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'America/Lima'}).format(new Date());
 root.innerHTML=pageHeader('Reportes e indicadores','Análisis detallado de servicios realizados e ingresos registrados')+form('FILTROS',select('Periodo:','period',['Semana','Mes','Año'],'Mes')+field('Fecha de referencia','reference',today,'date','required'),submit('Aplicar filtros'),'report-form')+'<div id="report-content" aria-live="polite"></div>';
 let drawId=0;
 const draw=async(period,reference)=>{
  const id=++drawId,target=root.querySelector('#report-content');target.setAttribute('aria-busy','true');
  target.innerHTML='<div class="loading-state" role="status">Consultando pagos y servicios…</div>';
  try{
   const report=await getReport(period,reference);if(id!==drawId)return;
   const fmt=d=>new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeZone:'America/Lima'}).format(d),range=report.range,previous=report.comparison;
   target.innerHTML=hint('Período: '+fmt(range.start)+' – '+fmt(new Date(range.end.getTime()-1))+'. Ingresos netos de pagos registrados, con sus rectificaciones. No incluye cotizaciones pendientes.')+`<div class="report-columns separated"><section class="panel"><h2 class="form-section-title">SERVICIOS REALIZADOS</h2>${table(['Tipo','Cantidad'],report.services.map(s=>[e(s.label),e(s.count)]),'No hay servicios finalizados en el periodo seleccionado.')}<h3>Servicios realizados más frecuentes</h3>${horizontalBars([...report.services].sort((a,b)=>b.count-a.count).slice(0,4),'services')}</section><section class="panel"><h2 class="form-section-title">INGRESOS REGISTRADOS</h2>${table(['Período','Ingresos'],report.months.map(m=>[e(m.label),money(m.cents)]))}<h3>Evolución de ingresos</h3>${incomeChart(report.months.map(m=>({month:/^\d{2}\/\d{2}$/.test(m.label)?m.label:m.label.slice(0,3),cents:m.cents})),Math.max(260,root.clientWidth/2-60))}<div class="report-total"><span>Total registrado</span><strong>${money(report.income)}</strong></div></section></div><section class="panel separated" id="historical-comparison"><h2 class="form-section-title">COMPARACIÓN CON EL PERÍODO ANTERIOR</h2><p>${fmt(range.previous)} – ${fmt(new Date(range.start.getTime()-1))}. Se comparan períodos completos de calendario.</p>${table(['Indicador','Período seleccionado','Período anterior','Diferencia'],[['Ingresos netos',money(report.income),money(previous.income),money(report.income-previous.income)],['Órdenes finalizadas',e(report.orders),e(previous.orders),e(report.orders-previous.orders)]])}</section>`;
  }catch(error){if(id===drawId)target.innerHTML=hint('No se pudieron consultar los reportes: '+error.message);throw error;}
  finally{if(id===drawId)target.removeAttribute('aria-busy');}
 };
 bindForm('report-form',async data=>{await draw(data.period,data.reference);notify('Filtros aplicados.');});await draw('Mes',today);
}

const userTabs=active=>`<nav class="tabs" aria-label="Secciones de usuarios"><a class="tab ${active==='usuarios'?'active':''}" href="#/usuarios" ${active==='usuarios'?'aria-current="page"':''}>${icon('user')}<span>Usuarios</span></a><a class="tab ${active==='roles'?'active':''}" href="#/usuarios/roles" ${active==='roles'?'aria-current="page"':''}>${icon('shield')}<span>Roles y permisos</span></a></nav>`;
function renderRoles({root,params,session},s,can){
 const matrix=rolePermissions(s),canManage=can('usuarios','roles');
 const roleOrder=realMode?s.roles.map(r=>r.name):ROLE_ORDER;
 const role=roleOrder.includes(params.get('rol'))?params.get('rol'):roleOrder.includes('Administrador')?'Administrador':roleOrder[0],locked=role===LOCKED_ROLE,editable=canManage&&!locked&&(!realMode||!session.roles.includes(role));
 const usersOf=r=>s.users.filter(u=>(u.roleNames||[u.role]).includes(r)),members=usersOf(role),granted=matrix[role]||{};
 const count=r=>usersOf(r).length;
 const memberText=members.length?members.slice(0,3).map(u=>e(u.name)).join(', ')+(members.length>3?` +${members.length-3}`:''):'Ninguno';
 const required=role==='Administrador'?REQUIRED_FOR_ADMIN:{};
 const roleList=roleOrder.map(r=>{const info=ROLE_INFO[r]||{tone:"gray",icon:"shield"};return `<a class="role-item ${r===role?'active':''}" href="#/usuarios/roles?rol=${encodeURIComponent(r)}" ${r===role?'aria-current="true"':''}><span class="role-bubble tone-${info.tone}">${icon(info.icon)}</span><span class="role-text"><strong>${e(r)}</strong><small>${count(r)} usuario${count(r)===1?'':'s'}</small></span>${icon('chevron')}</a>`;}).join('');
 const cards=PERMISSION_MODULES.map(m=>`<fieldset class="perm-card" ${editable?'':'disabled'}><legend><span class="perm-icon">${icon(m.icon)}</span>${e(m.label)}</legend>${m.actions.map(([action,label])=>{const mustKeep=required[m.id]?.includes(action);return `<label class="perm-check ${mustKeep?'perm-required':''}" ${mustKeep?'title="Obligatorio para el Administrador"':''}><input type="checkbox" data-module="${m.id}" data-action="${action}" ${granted[m.id]?.includes(action)?'checked':''} ${mustKeep?'disabled':''}><span>${e(label)}</span>${mustKeep?icon('lock'):''}</label>`;}).join('')}</fieldset>`).join('');
 const note=locked?hint('El Propietario siempre tiene acceso completo. Sus permisos no se pueden modificar.'):!canManage?hint('Tu rol puede consultar los permisos, pero no modificarlos.'):'';
 root.innerHTML=pageHeader('Usuarios y roles','Administra trabajadores, roles y permisos del sistema.')+userTabs('roles')+`<div class="roles-layout"><aside class="panel roles-list" aria-label="Roles del sistema"><h2>Roles del sistema</h2><p>Selecciona un rol para ver${canManage?' y modificar':''} sus permisos.</p>${roleList}</aside><section class="panel perms-panel"><div class="perms-heading"><div><h2>Permisos del rol: ${e(role)}</h2><p>Define qué puede hacer un usuario con este rol en cada módulo del sistema.</p></div><div class="role-members">${icon('users')}<div><span>Usuarios con este rol: <strong>${members.length}</strong></span><small>${memberText}</small></div></div></div>${note}<form id="perm-form" class="perm-form"><div class="perm-grid">${cards}</div><p class="form-error" role="alert" hidden></p><div class="perm-footer"><span class="perm-count"></span><div class="perm-buttons">${editable?`<button type="button" class="secondary-button" id="perm-reset">Restablecer valores</button><button type="button" class="secondary-button" id="perm-cancel">Cancelar</button><button type="submit" class="primary-button" id="perm-save" disabled>${icon('save')} Guardar cambios</button>`:''}</div></div></form></section></div><section class="panel quick-panel" aria-labelledby="quick-title"><div class="quick-heading">${icon('user')}<div><h2 id="quick-title">Vista rápida de usuario</h2><p>Consulta cómo se aplican los permisos de un usuario según su rol asignado.</p></div></div><div class="quick-select"><label for="quick-user">Usuario</label><select id="quick-user">${s.users.map(u=>`<option value="${e(u.id)}" ${u.id===(params.get('usuario')||session.id)?'selected':''}>${e(u.name)} · ${e(u.role)}</option>`).join('')}</select></div><div id="quick-body"></div></section>`;
 const form=root.querySelector('#perm-form'),boxes=[...form.querySelectorAll('input[type="checkbox"]')],counter=form.querySelector('.perm-count'),save=form.querySelector('#perm-save');
 const collect=()=>{const result={};boxes.filter(b=>b.checked).forEach(b=>{(result[b.dataset.module]??=[]).push(b.dataset.action);});return result;};
 const refresh=()=>{counter.textContent=`${countPermissions(collect())} de ${TOTAL_PERMISSIONS} permisos activos`;};
 form.addEventListener('change',ev=>{
  const box=ev.target.closest('input[type="checkbox"]');if(!box)return;
  const same=boxes.filter(b=>b.dataset.module===box.dataset.module),view=same.find(b=>b.dataset.action==='ver');
  if(box.dataset.action==='ver'&&!box.checked)same.forEach(b=>{if(!b.disabled)b.checked=false;});
  else if(box.checked&&view&&!view.checked)view.checked=true;
  refresh();if(save)save.disabled=false;
 });
 refresh();
 if(editable){
  root.querySelector('#perm-cancel').onclick=()=>go('usuarios/roles?rol='+encodeURIComponent(role));
  root.querySelector('#perm-reset').onclick=()=>{const dialog=showModal('Restablecer permisos',`<p class="dialog-intro">Los permisos del rol <strong>${e(role)}</strong> volverán a los valores iniciales del sistema.</p><div class="form-actions"><button type="button" class="secondary-button" data-x="cancel">Cancelar</button><button type="button" class="primary-button" data-x="ok">Restablecer</button></div>`);dialog.querySelector('[data-x="cancel"]').onclick=()=>dialog.close();dialog.querySelector('[data-x="ok"]').onclick=async ev=>{ev.currentTarget.disabled=true;try{await resetRolePermissions(role);dialog.close();notify(`Permisos de ${role} restablecidos.`);go('usuarios/roles?rol='+encodeURIComponent(role));}catch(error){ev.target.disabled=false;notify(error.message);}};};
  bindForm('perm-form',async ()=>{await saveRolePermissions(role,collect());notify(`Permisos del rol ${role} actualizados.`);go('usuarios/roles?rol='+encodeURIComponent(role));});
 }
 const quickBody=root.querySelector('#quick-body'),quickSelect=root.querySelector('#quick-user');
 const drawQuick=()=>{const u=s.users.find(x=>x.id===quickSelect.value);if(!u){quickBody.textContent='Sin usuarios disponibles.';return;}const perms={};for(const r of u.roleNames||[u.role])for(const [m,a] of Object.entries(matrix[r]||{}))perms[m]=[...new Set([...(perms[m]||[]),...a])];const chips=PERMISSION_MODULES.filter(m=>perms[m.id]).map(m=>`<span class="quick-chip"><strong>${e(m.label)}</strong>${perms[m.id].map(a=>m.actions.find(x=>x[0]===a)?.[1].split(' ')[0]).map(x=>e(x)).join(' · ')}</span>`).join('')||'<span class="quick-empty">Este rol no tiene accesos.</span>';
  quickBody.innerHTML=`<div class="quick-user"><span class="avatar-initials big">${e(u.name.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase())}</span><div class="quick-who"><strong>${e(u.name)}</strong><small>${e(u.email)}</small></div><div class="quick-fact"><span>Usuario</span><strong>${e(u.username)}</strong></div><div class="quick-fact"><span>Rol asignado</span><span class="tag tag-role">${e(u.role)}</span></div><div class="quick-fact"><span>Estado</span>${badge(u.active?'Activo':'Inactivo')}</div><div class="quick-info">${icon('info')}<span>Los permisos se heredan automáticamente del rol asignado: ${countPermissions(perms)} de ${TOTAL_PERMISSIONS} activos.</span></div></div><div class="quick-chips">${chips}</div>`;};
 quickSelect.onchange=drawQuick;drawQuick();
}
